78	  if (users.length < 5) {
79	    return `${users.map(formatUserName).join(", ")} reacted with ${reactionType.toLowerCase()}`;
80	  }
81	  return `${users.slice(0, 4).map(formatUserName).join(", ")} and ${users.length - 4} more reacted with ${reactionType.toLowerCase()}`;
